commands:
cd <WORKSPACE>/kanban-board
# Inject a VALID persisted envelope (proves loadState validation + hydration in a real browser)
agent-browser eval "(() => {
  const env = { version: 1, state: {
    boards: { b1: { id:'b1', name:'Persisted Board', columnOrder:['c1'] } },
    columns: { c1: { id:'c1', boardId:'b1', name:'Restored Col', cardOrder:['k1'] } },
    cards: { k1: { id:'k1', columnId:'c1', title:'Survived reload', labels:[], createdAt:'2026-07-02T00:00:00.000Z', updatedAt:'2026-07-02T00:00:00.000Z' } },
    boardOrder: ['b1'], activeBoardId: 'b1'
  }};
  localStorage.setItem('kanban-board:v1', JSON.stringify(env));
  return 'set';
})()" 2>&1 | tail -2
agent-browser open http://localhost:4173 2>&1 | tail -1
echo "=== snapshot after reload (should show Persisted Board / Restored Col / Survived reload) ==="
agent-browser snapshot -c 2>&1 | head -20
